async function request(path='',options={}){const r=await fetch(api+path,{credentials:'same-origin',cache:'no-store',...options});let body;try{body=await r.json()}catch{throw new Error(r.status===429?'Too many requests. Please wait a minute and retry.':'The workspace service did not respond. Please retry.')}if(!r.ok){const e=new Error(body.error||'Request failed');e.status=r.status;e.setup=body.setup;throw e}return body;}
function gate(message='',setup=false){data=null;selectedCandidate='';root.innerHTML=`<div class="gate"><img src="/assets/mark.svg" alt="MickyMarvels"><div class="eyebrow">OWNER WORKSPACE</div><h1>Micky’s team. Micky’s next move.</h1><p>Private Scrum Master staffing operations, hosted on Micky’s MickyMarvels site.</p>${setup?`<div class="notice">Owner setup is required before the workspace can be used. Configure the owner password in Netlify, then redeploy. No records are exposed.</div>`:`<form id="login"><label>Owner password<input type="password" name="password" autocomplete="current-password" minlength="20" required></label><button class="gold-button" type="submit">Sign in to workspace →</button></form>`}<p id="login-status" class="status-region error" role="status">${setup?'':esc(message)}</p><a href="/">← Back to MickyMarvels</a></div>`;document.getElementById('login')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),status=document.getElementById('login-status');button.disabled=true;status.textContent='Signing in…';try{await request('?action=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:new FormData(form).get('password')})});form.reset();await load()}catch(err){status.textContent=err.message;button.disabled=false}})}
async function load(){try{const result=await request();data=mergeCameroonDefaults(result.data||initial());etag=result.etag;if(!data.candidates.some(row=>row.id===selectedCandidate))selectedCandidate='';dirty=false;render()}catch(e){gate(e.message,e.setup)}}
function calculations(){const a=currentAssumptions();const has=ks=>ks.every(k=>a[k]!==''&&a[k]!==undefined&&Number.isFinite(+a[k])&&+a[k]>=0);const base=has(['bill','pay','hours','headcount']);const revenue=+a.bill * +a.hours * +a.headcount;const wages=+a.pay * +a.hours * +a.headcount;return {base,revenue,wages,wKnown:base&&has(['burden','benefits','overhead']),cKnown:base&&has(['contractorCost','overhead']),wCost:wages*(1+ +a.burden/100)+ +a.benefits * +a.headcount + +a.overhead,cCost:wages+ +a.contractorCost * +a.headcount + +a.overhead}}
function render(){root.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/"><img src="/assets/mark.svg" width="42" height="42" alt=""><span>MickyMarvels<small>STAFFING WORKSPACE</small></span></a><div class="scope">SCRUM MASTER PRACTICE</div><nav>${tabs.map((t,i)=>`<button data-view="${t}" class="${t===view?'selected':''}"><span aria-hidden="true">${symbols[i]}</span>${t}${t==='Candidates'?`<em>${data.candidates.length}</em>`:''}</button>`).join('')}</nav><a class="site-return" href="/">← Public demo site</a><div class="sidebar-note"><span class="spark">✦</span><b>Small team. Big possibilities.</b><p>Build Micky’s practice, one great placement at a time.</p><span class="pill dark">US CLIENT MARKET</span></div><div class="profile"><div class="avatar">MM</div><span>MickyMarvels LLC<small>Private owner workspace</small></span><span class="dot"></span></div></aside><div class="body"><header><button class="mobile" data-action="menu" aria-label="Toggle navigation" aria-expanded="false">☰</button><span class="breadcrumb">Workspace › <b>${esc(view)}</b></span><div class="header-right"><span class="save-status" id="save-status" role="status">${dirty?'Unsaved changes':'All changes saved'}</span><button class="outline" id="save" data-action="save" ${!dirty||busy?'disabled':''}>${busy?'Saving…':'Save changes'}</button><button class="logout" data-action="logout">Sign out</button></div></header><main><div class="page-heading"><div><div class="eyebrow">MICKYMARVELS / TALENT & DELIVERY</div><h1>${view==='Overview'?'Micky’s staffing business, in focus.':esc(view)}</h1><p>${view==='Overview'?'A clear view of Micky’s people, pipeline, and next move.':view==='Financial estimates'?'Compare the models. Refine the numbers as you learn.':view==='Worker scenarios'?'Compare US and Cameroon workers. See what remains after worker pay.':'Keep Micky’s details connected and the next step clear.'}</p></div><button class="outline export" data-action="export">↓ Export backup</button></div><div id="workspace-message" role="status"></div>${candidateScope()}${view==='Overview'?overview():view==='Financial estimates'?financial():view==='Worker scenarios'?cameroon():records()}<footer><span>© ${new Date().getFullYear()} MickyMarvels LLC</span><span>Hosted on MickyMarvels · Netlify</span></footer></main></div></div><dialog class="modal" id="editor" aria-label="Edit workspace record"></dialog>`;
root.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;query='';filter='All';render()}));root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action,b.dataset.id)));root.querySelector('#search')?.addEventListener('input',e=>{query=e.target.value;refreshList()});root.querySelector('#filter')?.addEventListener('change',e=>{filter=e.target.value;refreshList()});bindCandidateScope();bindCameroonInputs();root.querySelectorAll('[data-assumption]').forEach(input=>input.addEventListener('input',e=>{setAssumption(input.dataset.assumption,e.target.value===''?'':String(Math.max(0,+e.target.value)));markDirty();document.getElementById('model-results').innerHTML=modelResults()}));}
function refreshWorkerResults(){document.getElementById('cameroon-results').innerHTML=cameroonResults();document.getElementById('payroll-results').innerHTML=payrollResults();const company=document.getElementById('company-results');if(company)company.innerHTML=companyResults();const fields=document.getElementById('cam-calculated-fields');if(fields)fields.innerHTML=cameroonCalculatedFields();}
function bindCameroonInputs(){root.querySelectorAll('[data-payroll]').forEach(input=>input.addEventListener(input.tagName==='SELECT'?'change':'input',()=>{setAssumption(input.dataset.payroll,input.value);if(['camHealthPremiumXaf','camHealthEmployerShare'].includes(input.dataset.payroll)){setAssumption('camHealthMode','0');const mode=root.querySelector('[data-payroll="camHealthMode"]');if(mode)mode.value='0';}if(['camHealthWorkerXaf','camHealthCompanyXaf'].includes(input.dataset.payroll)){setAssumption('camHealthMode','1');const mode=root.querySelector('[data-payroll="camHealthMode"]');if(mode)mode.value='1';}if(input.dataset.payroll==='usStateOverride'){setAssumption('usOverrideState',currentAssumptions().usState);setAssumption('usOverrideFiling',currentAssumptions().usFiling);}markDirty();if(['usState','usFiling'].includes(input.dataset.payroll)){const override=root.querySelector('[data-payroll="usStateOverride"]');override.value=currentAssumptions().usOverrideState===currentAssumptions().usState&&currentAssumptions().usOverrideFiling===currentAssumptions().usFiling?currentAssumptions().usStateOverride:'';}refreshWorkerResults()}));root.querySelector('#worker-region')?.addEventListener('change',event=>{setAssumption('workerUs',event.target.value);dirty=true;render()});root.querySelectorAll('[data-cameroon]').forEach(input=>input.addEventListener('input',()=>{setAssumption(input.dataset.cameroon,input.value);if(['camCompanyTax','usCompanyTax'].includes(input.dataset.cameroon)){const mode=input.dataset.cameroon.startsWith('cam')?'camOwnerMode':'usOwnerMode';setAssumption(mode,'1');const control=root.querySelector('[data-payroll="'+mode+'"]');if(control)control.value='1';}markDirty();refreshWorkerResults()}));}
