function overview(){const c=calculations(),ready=data.candidates.filter(x=>x.readiness==='Ready for interview').length,active=data.placements.filter(x=>x.status==='Active').length,done=data.tasks.filter(x=>x.status==='Done').length,percent=data.tasks.length?Math.round(done/data.tasks.length*100):0;return `<section class="welcome"><div><span class="pill">MICKY’S PRACTICE, MICKY’S PACE</span><h2>Build the team.<br>Create the opportunity.</h2><p>Micky’s command center for placing exceptional Scrum Masters<br>with American companies.</p><button class="gold-button" data-action="first">＋ Add a candidate</button></div><div class="orb" aria-hidden="true"><span>MM</span><small>PEOPLE. DELIVERY. GROWTH.</small></div></section><div class="stats">${[['Candidates',data.candidates.length,'In Micky’s talent network','Candidates'],['Interview ready',ready,'Readiness confirmed','Candidates'],['Open opportunities',data.clients.filter(x=>!['Won','Lost'].includes(x.status)).length,'Client conversations','Clients'],['Active placements',active,'On assignment','Placements']].map(([label,n,sub,v])=>`<button class="stat" data-view="${v}"><div>${label}<span>↗</span></div><strong>${n}</strong><small>${sub}</small></button>`).join('')}</div><div class="overview-grid"><section class="panel"><div class="section-top"><div><h2>Micky’s next moves</h2><p>Turn the plan into progress.</p></div><button class="text-button" data-view="Next steps">View all ↗</button></div>${data.tasks.filter(t=>t.status!=='Done').slice(0,3).map(t=>`<div class="task-row"><button class="checkbox" data-action="complete" data-id="${esc(t.id)}" aria-label="Complete ${esc(t.name)}"></button><div><b>${esc(t.name)}</b><small>${esc(t.notes)}</small></div>${badge(t.priority,t.priority==='High')}</div>`).join('')||'<p class="empty-small">You’re caught up. Add Micky’s next action to keep moving.</p>'}<div class="progress-caption"><span>${done} of ${data.tasks.length} actions completed</span><b>${percent}%</b></div><progress class="progress" max="100" value="${percent}" aria-label="Action plan completion">${percent}%</progress></section><section class="panel finance-teaser"><div class="section-top"><div><h2>Know Micky’s numbers</h2><p>Illustrative monthly scenario</p></div><span>$</span></div><div class="estimate">${c.base?money(c.revenue):'Unknown'}<span>potential billings / month</span></div><div class="mini-rates"><span>Bill rate <b>${currentAssumptions().bill!==''?money(+currentAssumptions().bill)+'/hr':'Unknown'}</b></span><span>Pay rate <b>${currentAssumptions().pay!==''?money(+currentAssumptions().pay)+'/hr':'Unknown'}</b></span></div><p class="muted">Scenario only. Editable rates and hours; unconfirmed costs remain unknown.</p><button class="outline wide" data-view="Financial estimates">Compare W-2 & 1099 models ↗</button></section></div><section class="starting"><div class="icon-box">◇</div><div><h3>A workspace that grows with you</h3><p>No invented candidates or clients. Add what you know and leave the rest open.</p></div><span class="pill">SCRUM MASTERS ONLY</span></section>`}
function financial(){return `<div class="notice">Model comparison only. Confirm the actual work arrangement and country-specific requirements. US W-2 / 1099 labels do not decide how Cameroon-based workers should be engaged.</div><div class="finance-layout"><section class="panel"><h2>Scenario assumptions</h2><p>Starting rates are illustrative, not a signed placement. Blank means unknown. Enter 0 only when confirmed.</p><div class="form-grid">${assumptions.map(([key,label])=>`<label>${label}<input type="number" min="0" step="any" data-assumption="${key}" ${selectedCandidate&&key==='headcount'?'disabled':''} value="${esc(currentAssumptions()[key])}" placeholder="Unknown"></label>`).join('')}</div></section><div id="model-results">${modelResults()}</div></div><section class="panel"><h2>Decisions to confirm</h2><div class="decision-grid"><div><h3>W-2 employee</h3><p>Confirm payroll provider, employer registrations, taxes, insurance, benefits and work-state requirements.</p></div><div><h3>Independent contractor</h3><p>Confirm the genuine business arrangement, work location, control, client terms, insurance and classification review.</p></div><div><h3>Cameroon-based team</h3><p>Confirm local employment or contracting requirements, monthly compensation, currency assumptions and client approval for offshore access.</p></div></div></section>`}
function cameroon(){const {isUS}=workerScenario(currentAssumptions());const prefix=isUS?'us':'cam';return `<div class="notice">Planning scenario only, separate from the W-2 / 1099 estimates. Cameroon employment or contracting arrangements and client approval for offshore delivery must be confirmed.</div><p><a class="outline" href="#company-results">View Micky take-home after taxes ↓</a></p><div class="finance-layout"><section class="panel"><div class="eyebrow">WORKER SCENARIO / ${isUS?'US · USD':'CAMEROON · XAF'}</div><h2>Worker & rate assumptions</h2><p>Switch worker location to use its saved rates and costs. All rate inputs and client billing are in USD; Cameroon pay displays in CFA using Micky’s exchange rate. No workers or placements are created.</p><label>Worker location<select id="worker-region"><option value="1" ${isUS?'selected':''}>US Worker</option><option value="0" ${!isUS?'selected':''}>Cameroon Worker</option></select></label><div class="form-grid">${[[prefix+'Bill','Client bill rate / hour (USD)'],[prefix+'Pay','Worker pay rate / hour (USD)'],[prefix+'Hours','Billable hours / worker / month'],[prefix+'Workers','Number of workers'],[prefix+'Costs','Additional monthly costs / team (USD)'],[prefix+'CompanyTax','Manual owner/company tax reserve / month (USD, optional)'],...(isUS?[['usEmployerCosts','Employer payroll taxes and benefits / team / month (USD)']]:[]),...(!isUS?[['camUsdXaf','Exchange rate: CFA francs (XAF) per US dollar']]:[])].map(([key,label])=>`<label>${label}<input type="number" min="0" step="${key.endsWith('Workers')?'1':'any'}" data-cameroon="${key}" ${selectedCandidate&&key.endsWith('Workers')?'disabled':''} value="${esc(currentAssumptions()[key])}" placeholder="Unknown"></label>`).join('')}</div><p>Blank costs mean unknown. Enter 0 only when confirmed. Select Save changes to keep both scenarios and Micky’s selected location across devices.</p></section><div id="cameroon-results" aria-live="polite">${cameroonResults()}</div></div>${payrollInputs()}<div id="payroll-results" aria-live="polite">${payrollResults()}</div>${ownerTaxInputs()}<div id="company-results" aria-live="polite">${companyResults()}</div>`}
function cameroonResults(){const {isUS,assumptions}=workerScenario(currentAssumptions()),c=calculateCameroon(assumptions),payroll=calculateWorkerPayroll(currentAssumptions(),c),xaf=n=>n===null?'Unknown':n.toLocaleString('en-US',{maximumFractionDigits:0})+' XAF',usd=n=>n===null?'Unknown':n.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:0,maximumFractionDigits:2}),local=n=>isUS?usd(n):xaf(n!==null&&c.exchangeRate!==null?n*c.exchangeRate:null);return `<section class="panel"><div class="eyebrow">${isUS?'US WORKER / USD':'CAMEROON WORKER / CFA (XAF)'}</div><h2>Micky’s money after worker pay</h2><p>Gross spread before additional costs — not net profit.</p><dl class="cameroon-metrics">${[['Client revenue / worker / month (USD)',usd(c.revenuePerWorker)],['Worker pay / hour',local(assumptions.camPay!==''&&Number.isFinite(+assumptions.camPay)&&+assumptions.camPay>=0?+assumptions.camPay:null)],['Worker pay / worker / 2 weeks',local(c.biweeklyPayPerWorker)],['Worker pay / worker / month',local(c.monthlyPayPerWorker)],['Micky’s hourly gross spread / worker',local(c.hourlySpread)],['Micky’s biweekly gross spread / worker',local(c.biweeklyGrossSpreadPerWorker)],['Micky’s monthly gross spread / worker',local(c.grossSpreadPerWorker)],...(!isUS?[['Micky’s biweekly gross spread / worker (USD)',usd(c.biweeklyGrossSpreadPerWorker)],['Micky’s monthly gross spread / worker (USD)',usd(c.grossSpreadPerWorker)]]:[]),['Monthly client revenue / team (USD)',usd(c.revenue)],['Biweekly worker pay / team',local(c.biweeklyTeamPay)],['Monthly worker pay / team',local(c.workerPay)],['Biweekly gross spread / team before additional costs',local(c.biweeklyTeamGrossSpread)],['Monthly gross spread / team before additional costs',local(c.grossSpread)],['Gross margin before additional costs',c.grossMargin===null?'Unknown':c.grossMargin.toFixed(1)+'%'],['Additional monthly costs / team',local(c.additionalCosts)],...(isUS?[['Estimated contribution / team after additional costs',local(c.contribution)]]:[['Employer tax / CNPS charges / team / month',xaf(payroll.companyChargesTeamMonthly)],['Company-paid health insurance / team / month',xaf(payroll.companyHealthTeamMonthly)],['Estimated contribution / team after employer charges, insurance and additional costs',xaf(payroll.companyContributionTeamMonthly)]])].map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>${!isUS?'<p>CFA amounts = USD × Micky’s saved XAF-per-USD rate. This is a planning assumption, not a live quote. Converted amounts stay unknown without a positive rate; transfer fees are excluded.</p>':''}<p>Biweekly means every 2 weeks (26 periods/year). Estimates use monthly hours × 12 ÷ 26, not half a month. Actual pay depends on hours worked in each pay period.</p><p>Gross spread = client revenue − worker pay. Micky’s per-worker amount is before taxes, payroll burden, benefits, overhead and other costs. Estimated contribution deducts entered team costs. Gross margin is gross spread ÷ revenue; a zero-revenue margin is undefined.</p></section>`}
function payrollInputs(){const a=currentAssumptions(),isUS=a.workerUs==='1';const field=(key,label)=>`<label>${label}<input type="number" min="0" ${key==='camHealthEmployerShare'?'max="100"':''} step="any" data-payroll="${key}" value="${esc(key==='usStateOverride'&&(a.usOverrideState!==a.usState||a.usOverrideFiling!==a.usFiling)?'':a[key])}" placeholder="${['usStateOverride','camEmployerXaf'].includes(key)?'Automatic estimate':['camBasicXaf','camCnpsBaseXaf'].includes(key)?'Gross converted pay':'Unknown'}"></label>`;return `<section class="panel"><div class="eyebrow">${isUS?'US W-2 / EMPLOYEE DEDUCTIONS':'CAMEROON / EMPLOYEE TAX & INSURANCE'}</div><h2>${isUS?'Worker state & tax assumptions':'Tax and health insurance per worker'}</h2>${isUS?`<p>Choose the worker’s resident/work state. Single, standard W-4 assumptions are the editable starting point. State calculations are annual income-tax planning estimates; actual withholding may differ. No US health insurance is deducted.</p><div class="form-grid"><label>Worker state<select data-payroll="usState"><option value="">Select a state</option>${US_STATES.map(([code,name])=>`<option value="${code}" ${a.usState===code?'selected':''}>${name}</option>`).join('')}</select></label><label>Federal filing status<select data-payroll="usFiling"><option value="">Unknown</option>${FILING_STATUSES.map(([value,label])=>`<option value="${value}" ${a.usFiling===value?'selected':''}>${label}</option>`).join('')}</select></label>${field('usTaxYear','Tax year (automatic tables: 2026)')}<label>W-4 Step 2 multiple jobs<select data-payroll="usW4Multiple"><option value="">Unknown</option><option value="0" ${a.usW4Multiple==='0'?'selected':''}>Not checked</option><option value="1" ${a.usW4Multiple==='1'?'selected':''}>Checked</option></select></label>${field('usTaxCredits','W-4 Step 3 annual credits (USD)')}${field('usOtherIncome','W-4 Step 4(a) other annual income (USD)')}${field('usDeductions','W-4 Step 4(b) annual deductions (USD)')}${field('usExtraTax','Additional federal withholding / year (USD)')}${field('usStateOverride','Verified state withholding / worker / month (USD, optional)')}</div><p>The state override is used only for its selected state and filing status; blank uses the automatic estimate. Extra federal tax is entered as an annual planning total. Automatic state amounts are unavailable for California, Arkansas and Ohio until their current tables are verified; enter a verified state override for these states. Other state estimates omit some exemptions, credits and local rules; review the source notes below.</p>`:`<p>Salary bases, worker deductions and employer charges below calculate from the pay rate, hours and CFA exchange rate above. Choose the applicable CNPS scheme and confirmed risk group once; the amounts update automatically.</p><div class="form-grid"><label>CNPS family-benefit scheme<select data-payroll="camFamilyRate"><option value="">Unknown</option>${[['7','General / 7%'],['5.65','Agricultural / 5.65%'],['3.7','Private education / 3.70%']].map(([value,label])=>`<option value="${value}" ${a.camFamilyRate===value?'selected':''}>${label}</option>`).join('')}</select></label><label>Confirmed CNPS work-injury group<select data-payroll="camRiskRate"><option value="">Select confirmed risk group</option>${[['1.75','Group A / low risk / 1.75%'],['2.5','Group B / medium risk / 2.50%'],['5','Group C / high risk / 5.00%']].map(([value,label])=>`<option value="${value}" ${a.camRiskRate===value?'selected':''}>${label}</option>`).join('')}</select></label></div><div id="cam-calculated-fields">${cameroonCalculatedFields()}</div><h3 class="insurance-title">Health insurance — automatic split</h3><p>Enter the insurer’s monthly premium and the company-paid percentage. The worker and company amounts above calculate automatically. An insurance price cannot be inferred from salary. Leave it unknown until quoted, or enter a premium of 0 if no insurance cost is confirmed.</p><div class="form-grid">${field('camHealthPremiumXaf','Monthly insurer premium / worker (XAF)')}${field('camHealthEmployerShare','Company-paid share of premium (%)')}</div><details class="payroll-overrides"><summary>Optional manual overrides & tax settings</summary><p>These settings are optional. Leave salary-base and employer-total overrides blank to calculate them automatically. Existing saved overrides are preserved and identified above.</p><div class="form-grid"><label>Cameroon worker deductions<select data-payroll="camTaxMode"><option value="0" ${a.camTaxMode==='0'?'selected':''}>Automatic employee estimate</option><option value="1" ${a.camTaxMode==='1'?'selected':''}>Manual verified total</option></select></label>${field('camTaxYear','Cameroon tax year (automatic: 2026)')}${field('camBasicXaf','Override basic monthly salary for TDL (XAF)')}${field('camCnpsBaseXaf','Override CNPS monthly contribution salary (XAF)')}${field('camTaxXaf','Manual total worker tax / social deductions / month (XAF)')}${field('camEmployerXaf','Verified employer tax / CNPS total / worker / month (XAF, optional)')}<label>Health-insurance calculation<select data-payroll="camHealthMode"><option value="0" ${a.camHealthMode==='0'?'selected':''}>Calculate from premium and company share</option><option value="1" ${a.camHealthMode==='1'?'selected':''}>Use saved separate amounts</option></select></label>${field('camHealthWorkerXaf','Manual worker-paid health insurance / month (XAF)')}${field('camHealthCompanyXaf','Manual company-paid health insurance / month (XAF)')}</div><p>Worker totals in manual mode replace the automatic worker deduction total. An employer override replaces only employer tax/CNPS charges. Insurance stays separate. Avoid entering modeled charges or insurance again in additional costs.</p></details>`}<p>Use Save changes to keep these assumptions across devices.</p></section>`}
function cameroonCalculatedFields(){const a=currentAssumptions(),c=calculateCameroon(workerScenario(a).assumptions),p=calculateWorkerPayroll(a,c),health=calculateCameroonHealth(a),rate=a.camUsdXaf!==''&&Number.isFinite(+a.camUsdXaf)&&+a.camUsdXaf>0?+a.camUsdXaf:null,gross=c.monthlyPayPerWorker!==null&&rate!==null?c.monthlyPayPerWorker*rate:null,fmt=n=>n===null||n===undefined?'Unknown':n.toLocaleString('en-US',{maximumFractionDigits:0})+' XAF';const base=key=>a[key]===''?gross:Number.isFinite(+a[key])&&+a[key]>=0?+a[key]:null;const rows=[['Basic monthly salary for TDL',base('camBasicXaf'),a.camBasicXaf===''?'Calculated from gross pay':'Saved override'],['CNPS monthly contribution salary',base('camCnpsBaseXaf'),a.camCnpsBaseXaf===''?'Calculated from gross pay; caps applied to pension/family charges':'Saved override'],['Total worker tax / social deductions / month',p.monthly?.taxTotal,a.camTaxMode==='0'?'Automatically calculated':'Saved manual total'],['Employer tax / CNPS total / worker / month',p.automatic?.employerTotal,a.camEmployerXaf===''?'Automatically calculated; requires a confirmed risk group':'Saved employer override'],['Worker-paid health insurance / month',health.worker,a.camHealthMode==='0'?'Calculated from quoted premium and company share':'Saved separate amount'],['Company-paid health insurance / month',health.company,a.camHealthMode==='0'?'Calculated from quoted premium and company share':'Saved separate amount']];return `<div class="form-grid">${rows.map(([label,value,note])=>`<label>${label}<output class="calculated-output">${esc(fmt(value))}</output><small>${note}</small></label>`).join('')}</div>`}
function payrollResults(){const a=currentAssumptions(),{isUS,assumptions}=workerScenario(a),scenario=calculateCameroon(assumptions),p=calculateWorkerPayroll(a,scenario),fmt=v=>v===null||v===undefined?'Unknown':v.toLocaleString('en-US',isUS?{style:'currency',currency:'USD',maximumFractionDigits:2}:{maximumFractionDigits:0})+(isUS?'':' XAF');const rows=isUS?[['Gross worker pay','gross'],['Federal income-tax withholding estimate','federal'],['State income-tax planning estimate','state'],['Employee Social Security','socialSecurity'],['Employee Medicare (including additional Medicare)','medicare'],['Total estimated worker taxes','taxTotal'],['Estimated worker take-home','net']]:[['Gross worker pay','gross'],...(p.manual?[['Manual total worker tax / social deductions','manualTax']]:[['IRPP income tax','irpp'],['CAC surcharge on IRPP','cac'],['Worker CNPS pension','workerPension'],['Worker CFC housing levy','workerHousing'],['RAV audiovisual levy','rav'],['TDL local-development levy','tdl']]),['Total worker tax / social deductions','taxTotal'],['Worker-paid health insurance','workerInsurance'],['Estimated worker take-home','net']];return `<section class="panel payroll-panel"><div class="eyebrow">PER WORKER / ${isUS?'USD':'CFA (XAF)'}</div><h2>Estimated take-home pay</h2><div class="payroll-table-wrap"><table><thead><tr><th scope="col">Pay & deductions</th><th scope="col">Biweekly</th><th scope="col">Monthly</th></tr></thead><tbody>${rows.map(([label,key])=>`<tr><th scope="row">${label}</th><td>${fmt(p.biweekly?.[key])}</td><td>${fmt(p.monthly?.[key])}</td></tr>`).join('')}</tbody></table></div><p>Worker deductions are paid to the relevant tax authority or insurer, not retained as extra company earnings. Company gross spread is still client revenue minus gross worker pay. ${isUS?'Employer payroll taxes and other business costs are excluded unless separately entered.':'Modeled Cameroon employer charges and company-paid insurance are deducted from company contribution, separately from worker deductions.'}</p>${!isUS?cameroonEmployerResults(p,fmt):''}<details><summary>Calculation assumptions & source notes</summary>${p.notes.map(note=>`<p>${esc(note)}</p>`).join('')}<p>Biweekly figures use annual totals ÷ 26; monthly uses ÷ 12. Actual pay-period withholding and year-to-date caps may differ.</p>${isUS?`<p><a href="https://www.irs.gov/publications/p15t" target="_blank" rel="noopener noreferrer">IRS Publication 15-T (2026)</a> · <a href="https://www.irs.gov/taxtopics/tc751" target="_blank" rel="noopener noreferrer">IRS Social Security / Medicare</a> · <a href="https://github.com/edyda99/us-tax-engines" target="_blank" rel="noopener noreferrer">State planning data and limitations (MIT)</a></p>${p.state?`<p>State table year: ${esc(p.state.figureYear||'No wage income tax')}. ${esc(p.state._source||'No individual state wage income tax modeled.')}</p>`:''}`:`<p><a href="${CAMEROON_TAX_SOURCE}" target="_blank" rel="noopener noreferrer">Cameroon 2026 General Tax Code: sections 29, 34, 69; C 86; housing/FNE and RAV appendices</a> · <a href="${CAMEROON_CNPS_SOURCE}" target="_blank" rel="noopener noreferrer">CNPS contribution schedule</a>. Confirm actual obligations and benefit terms locally before payroll.</p>`}</details></section>`}
function cameroonEmployerResults(p,fmt){const a=p.automatic||{},rows=[['Employer CNPS pension',a.employerPension],['Employer CNPS family benefits',a.employerFamily],['Employer CNPS work injury',a.employerInjury],['Employer CFC housing levy',a.employerHousing],['Employer FNE employment levy',a.employerEmployment],['Employer tax / CNPS total (override if entered)',a.employerTotal],['Company-paid health insurance',p.companyHealthMonthly]];return `<h3>Employer costs per worker</h3><div class="payroll-table-wrap"><table><thead><tr><th scope="col">Company expense</th><th scope="col">Biweekly estimate</th><th scope="col">Monthly</th></tr></thead><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th><td>${fmt(value===null||value===undefined?null:value*12/26)}</td><td>${fmt(value)}</td></tr>`).join('')}</tbody></table></div><p>An employer override replaces the total above; automatic component rows remain reference estimates and are not added again. Company contribution also deducts Micky’s entered shared additional costs.</p>`}
function modelResults(){const c=calculations(),a=currentAssumptions();return `<section class="panel"><div class="eyebrow">MONTHLY MODEL COMPARISON</div><h2>What remains after costs?</h2><div class="comparison"><div>${badge('W-2 employee')}<h3>${c.wKnown?money(c.revenue-c.wCost):'Unknown'}</h3><p>Estimated contribution</p></div><div>${badge('1099 contractor',true)}<h3>${c.cKnown?money(c.revenue-c.cCost):'Unknown'}</h3><p>Estimated contribution</p></div></div><table><thead><tr><th>Monthly estimate</th><th>W-2</th><th>1099</th></tr></thead><tbody>${[['Client billings',c.base?money(c.revenue):'Unknown',c.base?money(c.revenue):'Unknown'],['Base worker pay',c.base?money(c.wages):'Unknown',c.base?money(c.wages):'Unknown'],['Total modeled costs',c.wKnown?money(c.wCost):'Unknown',c.cKnown?money(c.cCost):'Unknown'],['Contribution margin',c.wKnown&&c.revenue>0?((c.revenue-c.wCost)/c.revenue*100).toFixed(1)+'%':'Unknown',c.cKnown&&c.revenue>0?((c.revenue-c.cCost)/c.revenue*100).toFixed(1)+'%':'Unknown']].map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table><p>Contribution = billings − worker pay − entered model costs − overhead. Excludes unentered costs, nonbillable time and income tax.</p></section><section class="panel cash"><h3>Plan for the payroll gap</h3><p>Base-pay funding during the payment delay: <b>${c.base&&a.days!==''?money(c.wages * +a.days/30):'Unknown'}</b></p><p>Monthly worker pay × payment delay ÷ 30. Actual payroll and invoice cycles may require a larger reserve.</p></section>`}
function records(){if(view==='Candidates'&&selectedCandidate)return candidateProfileView();const noun=view==='Candidates'?'candidate':view==='Clients'?'opportunity':view==='Placements'?'placement':'action';const opts=specs[view].find(f=>f[0]==='status')[2];return `<section class="panel records"><div class="section-top"><div><h2>${view==='Candidates'?'Talent network':view==='Clients'?'Client pipeline':view==='Placements'?'Placement tracker':'Action plan'}</h2><p>${view==='Candidates'?'Track skills, readiness, training gaps and availability.':view==='Placements'?'Link Micky’s people to real client opportunities.':'Start with what you know. Fill in the details over time.'}</p></div><button class="gold-button" data-action="add">＋ Add ${noun}</button></div><div class="toolbar"><div class="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search records" placeholder="Search ${view.toLowerCase()}…" value="${esc(query)}"></div><select id="filter" aria-label="Filter status"><option>All</option>${opts.map(o=>`<option ${filter===o?'selected':''}>${o}</option>`).join('')}</select></div><div id="record-list">${list()}</div></section>`}
function list(){const rows=scopedRecords().filter(r=>JSON.stringify(r).toLowerCase().includes(query.toLowerCase())&&(filter==='All'||r.status===filter));if(!rows.length)return `<div class="empty"><div class="empty-icon">${symbols[tabs.indexOf(view)]}</div><h3>${query||filter!=='All'?'No matching records':'Micky’s '+view.toLowerCase()+' start here'}</h3><p>${query||filter!=='All'?'Try another search or status.':'Add Micky’s first record. Unknown details can stay blank.'}</p></div>`;return `<div class="record-grid">${rows.map(r=>{const name=r.name||data.candidates.find(c=>c.id===r.candidate)?.name||'Candidate unknown';const fields=view==='Candidates'?['location','skills','readiness','training']:view==='Clients'?['location','requirements','model','offshore']:view==='Placements'?['model','start','bill','pay']:['priority','owner','due'];return `<button class="record" data-action="${view==='Candidates'?'profile':'edit'}" data-id="${esc(r.id)}"><div class="record-top"><span class="record-avatar">${esc(name.slice(0,2).toUpperCase())}</span>${badge(r.status)}</div><h3>${esc(name)}</h3>${view==='Placements'?`<p>${esc(data.clients.find(c=>c.id===r.client)?.name||'Client unknown')}</p>`:''}${fields.map(k=>`<div class="detail"><span>${esc(specs[view].find(f=>f[0]===k)?.[1]||k)}</span><b>${unknown(r[k])}</b></div>`).join('')}<div class="record-footer">View & edit details <span>↗</span></div></button>`}).join('')}</div>`}
function refreshList(){document.getElementById('record-list').innerHTML=list();root.querySelectorAll('#record-list [data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action,b.dataset.id)))}
function editor(id){editing=id?data[keys[view]].find(r=>r.id===id):null;const d=document.getElementById('editor');d.innerHTML=`<form id="record-form"><div class="section-top"><h2>${editing?'Edit':'Add'} ${view==='Next steps'?'action':view.slice(0,-1).toLowerCase()}</h2><button class="close" type="button" id="close" aria-label="Close editor">×</button></div><p>All roles are Scrum Master. Leave unconfirmed details blank.</p><div class="form-grid">${specs[view].map(([k,label,type])=>{const v=editing?.[k]??(k==='candidate'?selectedCandidate:k==='placement'&&selectedCandidate?data.candidateProfiles?.[selectedCandidate]?.placementId:'')??'';let input;if(type==='region'){input=`<select name="${k}"><option value="">Unknown / choose</option><option value="1" ${v==='1'?'selected':''}>US Worker</option><option value="0" ${v==='0'?'selected':''}>Cameroon Worker</option></select>`}else if(type==='state'){input=`<select name="${k}"><option value="">Unknown</option>${US_STATES.map(([code,name])=>`<option value="${code}" ${v===code?'selected':''}>${name}</option>`).join('')}</select>`}else if(type==='placementOptional'){const choices=selectedCandidate?data.placements.filter(p=>p.candidate===selectedCandidate):data.placements;input=`<select name="${k}"><option value="">Unlinked</option>${choices.map(p=>`<option value="${esc(p.id)}" ${v===p.id?'selected':''}>${esc(placementLabel(p))}</option>`).join('')}</select>`}else if(Array.isArray(type)){input=`<select name="${k}"><option value="">Unknown</option>${type.map(o=>`<option value="${esc(o)}" ${v===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`}else if(type==='candidate'||type==='candidateOptional'||type==='client'){const choices=data[type==='client'?'clients':'candidates'];input=`<select name="${k}" ${type==='candidateOptional'?'':'required'}><option value="">${type==='candidateOptional'?'Unlinked':'Select '+type}</option>${choices.map(c=>`<option value="${esc(c.id)}" ${v===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`}else if(type==='textarea'){input=`<textarea name="${k}" maxlength="10000" placeholder="Unknown">${esc(v)}</textarea>`}else{input=`<input name="${k}" value="${esc(v)}" type="${type==='number'?'number':type==='date'?'date':'text'}" ${type==='required'?'required':''} ${type==='number'?'min="0" step="any"':''} maxlength="10000" placeholder="Unknown">`}return `<label>${label}${input}</label>`}).join('')}</div>${view==='Placements'&&(!data.candidates.length||!data.clients.length)?'<p class="notice">Add a candidate and a client opportunity before creating a placement.</p>':''}<div class="modal-actions">${editing?'<button class="delete" type="button" id="delete">Delete record</button>':''}<button type="button" class="outline" id="cancel">Cancel</button><button type="submit" class="gold-button">Apply changes</button></div><small>Apply to workspace, then select Save changes to store Micky’s updates.</small></form>`;d.showModal();d.querySelector('#close').onclick=()=>d.close();d.querySelector('#cancel').onclick=()=>d.close();d.querySelector('#delete')?.addEventListener('click',()=>{const key=keys[view];if(key==='candidates'&&data.tasks.some(t=>t.candidate===editing.id)){alert('Unlink candidate tasks before deleting this record.');return}if(['candidates','clients'].includes(key)&&data.placements.some(p=>p[key==='candidates'?'candidate':'client']===editing.id)){alert('Remove linked placements before deleting this record.');return}if(confirm('Delete this record? Export a backup first if you may need it later.')){data[key]=data[key].filter(r=>r.id!==editing.id);if(key==='candidates'){if(data.candidateProfiles)delete data.candidateProfiles[editing.id];selectedCandidate='';}if(key==='placements'){for(const p of Object.values(data.candidateProfiles||{}))if(p.placementId===editing.id)p.placementId='';for(const task of data.tasks)if(task.placement===editing.id)task.placement='';}dirty=true;d.close();render()}});d.querySelector('form').onsubmit=e=>{e.preventDefault();const row={...editing,...Object.fromEntries(new FormData(e.currentTarget))};row.id=editing?.id||crypto.randomUUID();try{saveLinkedRecord(data,keys[view],row)}catch(error){alert(error.message);return;}if(view==='Candidates'){selectedCandidate=row.id;ensureCandidateProfile(data,row.id);}if(view==='Placements'){ensureCandidateProfile(data,row.candidate).placementId=row.id;selectedCandidate=row.candidate;}dirty=true;d.close();render()}}
async function action(name,id){if(name==='new-candidate'){selectedCandidate='';view='Candidates';render();editor();return}if(name==='profile'){selectCandidate(id);view='Candidates';render();return}if(name==='edit-profile'){view='Candidates';editor(selectedCandidate);return}if(name==='add-placement'){view='Placements';render();editor();return}if(name==='add-task'){view='Next steps';render();editor();return}if(name==='open-placement'){view='Placements';editor(id);return}if(name==='menu'){const el=root.querySelector('.sidebar');el.classList.toggle('open');root.querySelector('.mobile').setAttribute('aria-expanded',el.classList.contains('open'));return}if(name==='add'||name==='edit'){if(name==='add'&&view==='Candidates')selectedCandidate='';editor(id);return}if(name==='first'){selectedCandidate='';view='Candidates';query='';filter='All';render();editor();return}if(name==='complete'){data.tasks=data.tasks.map(t=>t.id===id?{...t,status:'Done'}:t);dirty=true;render();return}if(name==='export'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({format:'mickymarvels-workspace-v1',exportedAt:new Date().toISOString(),data},null,2)],{type:'application/json'}));a.href=url;a.download='mickymarvels-staffing-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(name==='logout'){if(dirty&&!confirm('You have unsaved changes. Sign out and discard them?'))return;try{await request('?action=logout',{method:'POST'});dirty=false;gate()}catch(e){showMessage(e.message)}return}if(name==='save'){if(busy||!dirty)return;busy=true;const save=document.getElementById('save');save.disabled=true;save.textContent='Saving…';const snapshot=JSON.stringify(data);try{const r=await request('',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:JSON.parse(snapshot),etag})});etag=r.etag;dirty=JSON.stringify(data)!==snapshot;document.getElementById('save-status').textContent=dirty?'Unsaved changes':'All changes saved';showMessage('')}catch(e){showMessage(e.status===401?'Micky’s session expired. Export a backup of unsaved changes, then sign out and sign in again.':e.message);document.getElementById('save-status').textContent='Save failed'}finally{busy=false;const current=document.getElementById('save');if(current){current.disabled=!dirty;current.textContent='Save changes'}}}}
function showMessage(message){const el=document.getElementById('workspace-message');if(el){el.className=message?'notice':'';el.textContent=message}}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
load();

function companyResults(){const result=calculateCompanyTakeHome(currentAssumptions()),fmt=value=>value===null?'Unknown':value.toLocaleString('en-US',result.isUS?{style:'currency',currency:'USD',maximumFractionDigits:2}:{maximumFractionDigits:0})+(result.isUS?'':' XAF');const labels=[['Client revenue','revenue'],['Gross worker pay','workerPay'],['Micky gross spread before expenses','spread'],['Employer taxes / CNPS and benefits','employer'],...(result.employer===null&&result.knownEmployer!==null?[['Known employer charges included in subtotal (incomplete)','knownEmployer']]:[]),['Company-paid health insurance','insurance'],['Additional operating expenses','costs'],[result.automaticTax?'Automatic US owner federal tax reserve'+(result.taxProvisional?' (provisional)':''):'Manual owner/company tax reserve','tax'],...(result.missing.length?[['Final take-home after all expenses (awaiting missing costs)','net']]:[]),[result.missing.length?result.tax!==null?'Micky provisional take-home after known expenses and owner taxes':'Micky subtotal before unconfirmed owner taxes':'Micky estimated take-home after expenses and owner taxes','subtotal']];return `<section class="panel payroll-panel"><div class="eyebrow">MICKY / COMPANY SUMMARY · ${result.isUS?'USD':'CFA (XAF)'}</div><h2>Micky take-home</h2>${companyTakeHomeCards(result,fmt)}<p>Team totals for the selected worker scenario. Update the rate and expense assumptions above, then Save changes.</p><div class="payroll-table-wrap"><table><thead><tr><th scope="col">Revenue & expenses</th><th scope="col">Biweekly</th><th scope="col">Monthly</th></tr></thead><tbody>${labels.map(([label,key])=>`<tr><th scope="row">${label}</th><td>${fmt(result[key]===null?null:result[key]*12/26)}</td><td>${fmt(result[key])}</td></tr>`).join('')}</tbody></table></div><p>Micky ${result.missing.length?'provisional subtotal':'estimated take-home'} per worker: <strong>${fmt(result.subtotalPerWorker)}</strong> monthly · <strong>${fmt(result.subtotalPerWorker===null?null:result.subtotalPerWorker*12/26)}</strong> biweekly.</p><p>${result.missing.length?'The provisional subtotal excludes unconfirmed costs and will decrease when they are entered. Needed for final take-home: '+esc(result.missing.join(', '))+'.':'All expense categories have entered or modeled amounts.'} Blank expenses remain unknown; enter 0 only when confirmed. Additional costs should include transfer fees, overhead and other business expenses, excluding charges already shown separately.</p>${ownerTaxBreakdown(result)}<p>This is estimated company cash remaining after the listed expenses and entered tax provision, not a personal paycheck or a guarantee of net profit. US employer taxes and benefits require an entered total; employee paycheck deductions are already part of gross worker pay and are not deducted twice. Automatic owner tax uses the default single-owner LLC model above; manual mode uses the entered reserve instead. This estimates the selected scenario alone; do not add separate US and Cameroon estimates to determine a combined annual tax bill. Biweekly uses monthly × 12 ÷ 26.</p></section>`}

function ownerTaxInputs(){const a=currentAssumptions(),prefix=a.workerUs==='1'?'us':'cam',select=(key,label,options)=>`<label>${label}<select data-payroll="${key}">${options.map(([value,text])=>`<option value="${value}" ${a[key]===value?'selected':''}>${text}</option>`).join('')}</select></label>`,input=(key,label)=>`<label>${label}<input type="number" min="0" step="any" data-payroll="${key}" value="${esc(a[key])}" placeholder="Unknown"></label>`;return `<section class="panel"><div class="eyebrow">MICKY / US OWNER TAX ASSUMPTIONS</div><h2>LLC tax treatment & automatic reserve</h2><p>Default single-owner treatment is a planning assumption until confirmed. These owner settings are separate from worker payroll settings and save with the workspace.</p><div class="form-grid">${select('ownerTreatment','LLC federal tax treatment',[['0','Single-owner LLC — default / Schedule C'],['1','S corporation election'],['2','C corporation election'],['3','Unknown / confirm with tax adviser']])}${select(prefix+'OwnerMode','Owner tax reserve calculation',[['0','Automatic federal estimate'],['1','Use saved manual monthly reserve']])}${input('ownerYear','Owner tax year (automatic: 2026)')}${select('ownerFiling','Owner federal filing status',[['0','Single'],['1','Married filing jointly'],['2','Head of household'],['3','Married filing separately']])}${input('ownerWages','Owner annual W-2 wages (USD)')}${input('ownerSpouseWages','Spouse annual W-2 wages (USD, joint return only)')}${input('ownerOtherIncome','Other annual ordinary income (USD, excludes wages and this scenario)')}</div><p>Starting assumptions: 2026, single, standard deduction, no other wages or income. Edit them to match Micky’s circumstances. Automatic mode assumes a US citizen/resident actively operating a Schedule C business, ordinary cash profit, and all entered business costs deductible. S/C corporation elections require a verified manual reserve; no corporate tax estimate is invented.</p><p>Federal planning reserve only: excludes state/local taxes, QBI deduction, tax credits, itemized and age-related deductions, retirement contributions, foreign tax credits, other self-employment businesses and prior payments/withholding. QBI and credits may reduce actual tax. Add an adviser’s complete reserve in manual mode for circumstances outside this model.</p></section>`}
function ownerTaxBreakdown(result){if(!result.automaticTax)return '';const t=result.ownerTax,usd=n=>n===null?'Unknown':n.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2});return `<h3>US owner federal reserve — USD</h3><p>${result.taxProvisional?'Provisional: based on profit after known expenses only; missing expenses will change this estimate.':'Based on annualized profit from this scenario after operating expenses, before owner tax.'}</p><div class="payroll-table-wrap"><table><thead><tr><th scope="col">Owner tax estimate</th><th scope="col">Biweekly reserve</th><th scope="col">Monthly reserve</th></tr></thead><tbody>${[['Self-employment tax',t.selfEmployment],['Incremental federal income tax',t.incomeTax],['Additional Medicare tax',t.additionalMedicare],['Total federal reserve',t.annual]].map(([label,annual])=>`<tr><th scope="row">${label}</th><td>${usd(annual===null?null:annual/26)}</td><td>${usd(annual===null?null:annual/12)}</td></tr>`).join('')}</tbody></table></div><p>Income tax is the increase from adding this business profit to the entered other income, using the standard deduction and a deduction for half of regular self-employment tax. This reserve is not the amount still due after tax payments. <a href="https://www.irs.gov/irb/2025-45_IRB" target="_blank" rel="noopener noreferrer">2026 IRS brackets and deductions</a> · <a href="https://www.irs.gov/taxtopics/tc554" target="_blank" rel="noopener noreferrer">Self-employment tax</a> · <a href="https://www.irs.gov/taxtopics/tc560" target="_blank" rel="noopener noreferrer">Additional Medicare tax</a></p>`}

function companyTakeHomeCards(result,fmt){const a=currentAssumptions(),workers=Number(a[result.isUS?'usWorkers':'camWorkers']),display=companyTakeHomeDisplay(result,workers,Number(a.camUsdXaf)),usd=n=>n===null?'Unknown':n.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2});return `<div class="micky-take-home" role="region" aria-label="Micky take-home after taxes"><div class="eyebrow">${display.provisional?'PROVISIONAL ESTIMATE':'SCENARIO ESTIMATE'} · AFTER OWNER TAX RESERVE</div><h3>Micky take-home after taxes</h3><div class="take-home-cards"><div><span>Monthly · team</span><strong>${fmt(display.monthly)}</strong>${!result.isUS?`<small>${usd(display.monthlyUsd)} USD equivalent</small>`:''}</div><div><span>Biweekly · team</span><strong>${fmt(display.biweekly)}</strong></div><div><span>Monthly · per worker</span><strong>${fmt(display.perWorker)}</strong></div></div>${!result.isUS?`<div class="take-home-usd"><h3>Micky take-home in US dollars</h3><div class="form-grid"><label>Monthly take-home after taxes & expenses (USD)<output class="calculated-output">${usd(display.monthlyUsd)}</output></label><label>Biweekly take-home after taxes & expenses (USD)<output class="calculated-output">${usd(display.biweeklyUsd)}</output></label><label>Monthly take-home per worker (USD)<output class="calculated-output">${usd(display.perWorkerUsd)}</output></label><label>Conversion rate used (XAF per USD)<output class="calculated-output">${Number.isFinite(+a.camUsdXaf)&&+a.camUsdXaf>0?esc(a.camUsdXaf):'Unknown'}</output></label></div><p>Calculated automatically: CFA take-home ÷ the saved XAF-per-USD rate. Change the exchange-rate field in Worker & rate assumptions to update these amounts. ${display.provisional?'Provisional: unconfirmed expenses are excluded.':'Includes all listed expenses and the owner tax reserve.'} Transfer fees are included only if entered in additional costs.</p></div>`:''}<p>${esc(display.message)} ${result.automaticTax?'Federal estimate only; state/local taxes and other exclusions are described in the owner assumptions.':'Uses the saved manual owner/company tax reserve.'}</p><div class="take-home-equation">Before owner tax: <b>${fmt(result.beforeTax)}</b> − owner tax reserve: <b>${fmt(result.tax)}</b> = after tax: <b>${fmt(display.monthly)}</b> / month</div></div>`}

function currentAssumptions(){return selectedCandidate?profileAssumptions(data,selectedCandidate):data.assumptions}
function setAssumption(key,value){if(selectedCandidate)setProfileAssumption(data,selectedCandidate,key,value);else data.assumptions[key]=value}
function selectCandidate(id){selectedCandidate=data.candidates.some(row=>row.id===id)?id:'';if(selectedCandidate){const existed=Object.hasOwn(data.candidateProfiles||{},selectedCandidate);ensureCandidateProfile(data,selectedCandidate);if(!existed)dirty=true;}query='';filter='All'}
function placementLabel(placement){return `${data.clients.find(client=>client.id===placement.client)?.name||'Unknown client'} · ${placement.status||'Unknown status'}${placement.start?' · '+placement.start:''}`}
function candidateScope(){const context=selectedCandidate?candidateContext(data,selectedCandidate):null,profile=selectedCandidate?data.candidateProfiles?.[selectedCandidate]:null;return `<section class="panel candidate-scope"><div class="form-grid"><label>Selected candidate<select id="candidate-scope"><option value="">Workspace overview / shared scenarios</option>${data.candidates.map(c=>`<option value="${esc(c.id)}" ${selectedCandidate===c.id?'selected':''}>${esc(c.name||'Unnamed candidate')}</option>`).join('')}</select></label>${context?`<label>Rates and assignment<select id="placement-scope"><option value="">Candidate’s saved planning rates</option>${context.placements.map(p=>`<option value="${esc(p.id)}" ${profile?.placementId===p.id?'selected':''}>${esc(placementLabel(p))}</option>`).join('')}</select></label>`:''}</div><p>${context?`Viewing <b>${esc(context.candidate.name)}</b>. Placements, clients, tasks and both estimate tabs follow this person. ${profile?.placementId?'Rates come from the selected placement; rate edits update that placement.':'Planning rates are saved separately for this person; no team rates are copied.'} Estimates use one worker. Owner-tax estimates are scenario comparisons, not amounts to add across people.`:'Choose a candidate to see their profile and linked records. Workspace-wide assumptions stay separate.'}</p>${context?'<div class="workspace-actions"><button class="outline" data-view="Candidates">View candidate profile</button><button class="outline" data-action="new-candidate">＋ Add another candidate</button><button class="outline" data-view="Placements">Linked placements</button><button class="outline" data-view="Financial estimates">Financial estimates</button><button class="outline" data-view="Worker scenarios">Pay & take-home</button></div>':''}</section>`}
function bindCandidateScope(){root.querySelector('#candidate-scope')?.addEventListener('change',event=>{selectCandidate(event.target.value);render()});root.querySelector('#placement-scope')?.addEventListener('change',event=>{const profile=ensureCandidateProfile(data,selectedCandidate);profile.placementId=event.target.value;dirty=true;render()})}
function scopedRecords(){if(!selectedCandidate)return data[keys[view]];const context=candidateContext(data,selectedCandidate);return view==='Placements'?context.placements:view==='Clients'?context.clients:view==='Next steps'?context.tasks:data.candidates}
function candidateProfileView(){const context=candidateContext(data,selectedCandidate),c=context.candidate,a=currentAssumptions(),scenario=calculateCameroon(workerScenario(a).assumptions),p=calculateWorkerPayroll(a,scenario),company=calculateCompanyTakeHome(a),isUS=a.workerUs==='1',fmt=n=>n===null||n===undefined?'Unknown':n.toLocaleString('en-US',isUS?{style:'currency',currency:'USD',maximumFractionDigits:2}:{maximumFractionDigits:0})+(isUS?'':' XAF');return `<section class="panel candidate-profile"><div class="section-top"><div><div class="eyebrow">CANDIDATE PROFILE</div><h2>${esc(c.name)}</h2><p>${badge(c.status)} ${esc(c.location||'Work location unknown')}</p></div><button class="gold-button" data-action="edit-profile">Edit candidate details</button></div><dl class="profile-details">${specs.Candidates.filter(([key])=>key!=='name').map(([key,label])=>`<div><dt>${esc(label)}</dt><dd>${key==='workerUs'?c.workerUs==='1'?'US Worker':c.workerUs==='0'?'Cameroon Worker':'Unknown':key==='usState'?esc(US_STATES.find(([code])=>code===c.usState)?.[1]||'Unknown'):unknown(c[key])}</dd></div>`).join('')}</dl></section><section class="panel payroll-panel"><div class="section-top"><div><h2>Pay & financial snapshot</h2><p>${esc(data.candidateProfiles[selectedCandidate].placementId?'Selected placement rates':'Candidate-specific planning rates')} · one worker · ${isUS?'USD':'CFA (XAF)'}. Figures remain planning estimates.</p></div><button class="outline" data-view="Worker scenarios">Edit pay & tax assumptions</button></div><div class="payroll-table-wrap"><table><thead><tr><th>Amount</th><th>Biweekly</th><th>Monthly</th></tr></thead><tbody>${profileSnapshotRows(p,company,Number(a.camUsdXaf)).map(row=>`<tr><th scope="row">${esc(row.label)}</th><td>${fmt(row.biweekly)}${!isUS?`<small class="snapshot-usd">${snapshotUsd(row.biweeklyUsd)} USD</small>`:''}</td><td>${fmt(row.monthly)}${!isUS?`<small class="snapshot-usd">${snapshotUsd(row.monthlyUsd)} USD</small>`:''}</td></tr>`).join('')}</tbody></table></div>${!isUS?`<p>USD equivalents use this candidate’s saved exchange rate: ${a.camUsdXaf!==''&&+a.camUsdXaf>0?esc(a.camUsdXaf)+' XAF per USD':'Unknown'}. Amounts convert automatically when the rate or pay changes.</p>`:''}${company.missing.length?`<p class="notice">Final Micky take-home needs: ${esc(company.missing.join(', '))}. Any provisional amount excludes unconfirmed costs.</p>`:''}<button class="outline" data-view="Worker scenarios">View Micky take-home & expenses</button><p>Client bill rate: <b>${a.bill===''?'Unknown':money(+a.bill)+'/hour'}</b> · Worker pay rate: <b>${a.pay===''?'Unknown':money(+a.pay)+'/hour'}</b> · Monthly hours: <b>${esc(a.hours||'Unknown')}</b>. Unknown costs remain unknown. Company results are for this person and assignment only.</p><button class="outline" data-view="Financial estimates">Compare financial models</button></section><section class="panel"><div class="section-top"><h2>Placements & clients (${context.placements.length})</h2><button class="outline" data-action="add-placement">＋ Add linked placement</button></div>${context.placements.length?context.placements.map(row=>`<div class="profile-linked"><div><b>${esc(placementLabel(row))}</b><p>Bill: ${row.bill===undefined||row.bill===''?'Unknown':money(+row.bill)+'/hr'} · Pay: ${row.pay===undefined||row.pay===''?'Unknown':money(+row.pay)+'/hr'} · Monthly hours: ${esc(row.hours||'Unknown')}</p></div><button class="outline" data-action="open-placement" data-id="${esc(row.id)}">View / edit placement</button></div>`).join(''):'<p>No linked placements yet. Add a client opportunity, then link a placement to this candidate.</p>'}</section><section class="panel"><div class="section-top"><h2>Linked next steps (${context.tasks.length})</h2><button class="outline" data-action="add-task">＋ Add linked task</button></div>${context.tasks.map(t=>`<div class="profile-linked"><div><b>${esc(t.name)}</b><p>${esc(t.notes)}</p></div>${badge(t.status)}</div>`).join('')||'<p>No linked tasks yet. Existing unassigned tasks remain in the workspace view.</p>'}</section>`}

function snapshotUsd(value){return value===null?'Unknown':value.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2})}
